<#
.SYNOPSIS
  Downloads prebuilt x64 MSVC dependencies for libfreenect2 and writes a CMake
  initial-cache file pointing at them.

.DESCRIPTION
  Fetches official binary releases of libusb, libjpeg-turbo, GLFW and the
  Khronos OpenCL SDK into -DestDir, then generates <DestDir>/deps.cmake to be
  passed to CMake with `-C`. Explicit cache paths are used instead of relying
  on the Find modules' search order, because GitHub's Windows runners ship
  unrelated copies of some libraries (e.g. Strawberry Perl's c\lib).

  Already-extracted dependencies are reused, so the directory can be cached.

  Requires 7-Zip (7z.exe) on PATH or in its default install location.

.EXAMPLE
  ./.github/scripts/fetch-windows-deps.ps1 -DestDir deps-win
  cmake -S . -B build -G Ninja -C deps-win/deps.cmake
#>
[CmdletBinding()]
param(
  [Parameter(Mandatory)] [string] $DestDir,
  [string] $LibUsbVersion     = '1.0.30',
  [string] $TurboJpegVersion  = '3.2.0',
  [string] $GlfwVersion       = '3.5.1',
  [string] $OpenClSdkVersion  = 'v2026.05.29'
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'  # Invoke-WebRequest is very slow with the progress bar

$DestDir = [IO.Path]::GetFullPath((New-Item -ItemType Directory -Force $DestDir).FullName)
$downloads = Join-Path $DestDir '_downloads'
New-Item -ItemType Directory -Force $downloads | Out-Null

$sevenZip = (Get-Command 7z -ErrorAction SilentlyContinue).Source
if (-not $sevenZip) { $sevenZip = Join-Path $env:ProgramFiles '7-Zip\7z.exe' }
if (-not (Test-Path $sevenZip)) { throw '7-Zip (7z.exe) not found' }

function Get-Archive([string] $Url) {
  $file = Join-Path $downloads ([IO.Path]::GetFileName($Url))
  if (-not (Test-Path $file)) {
    Write-Host "Downloading $Url"
    Invoke-WebRequest -Uri $Url -OutFile "$file.part" -MaximumRetryCount 3 -RetryIntervalSec 5
    Move-Item "$file.part" $file
  }
  return $file
}

# Extracts $Url into $DestDir\$Name. $StripDir is the top-level folder inside
# the archive to unwrap, if any.
function Install-Dependency([string] $Name, [string] $Url, [string] $Marker, [string] $StripDir) {
  $target = Join-Path $DestDir $Name
  if (Test-Path (Join-Path $target $Marker)) {
    Write-Host "$Name already present, skipping"
    return $target
  }
  if (Test-Path $target) { Remove-Item -Recurse -Force $target }

  $archive = Get-Archive $Url
  $tmp = Join-Path $DestDir "_extract_$Name"
  if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }
  & $sevenZip x -y "-o$tmp" $archive | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "7z failed to extract $archive" }

  $src = if ($StripDir) { Join-Path $tmp $StripDir } else { $tmp }
  Move-Item $src $target
  if (Test-Path $tmp) { Remove-Item -Recurse -Force $tmp }

  if (-not (Test-Path (Join-Path $target $Marker))) { throw "${Name}: expected $Marker after extraction" }
  return $target
}

$libusb = Install-Dependency 'libusb' `
  "https://github.com/libusb/libusb/releases/download/v$LibUsbVersion/libusb-$LibUsbVersion.7z" `
  'VS2022\MS64\dll\libusb-1.0.dll'

# The official Windows package is an NSIS installer; 7-Zip unpacks it without installing.
$turbojpeg = Install-Dependency 'libjpeg-turbo64' `
  "https://github.com/libjpeg-turbo/libjpeg-turbo/releases/download/$TurboJpegVersion/libjpeg-turbo-$TurboJpegVersion-vc-x64.exe" `
  'bin\turbojpeg.dll'

$glfw = Install-Dependency 'glfw' `
  "https://github.com/glfw/glfw/releases/download/$GlfwVersion/glfw-$GlfwVersion.bin.WIN64.zip" `
  'lib-vc2022\glfw3.dll' "glfw-$GlfwVersion.bin.WIN64"

$opencl = Install-Dependency 'opencl' `
  "https://github.com/KhronosGroup/OpenCL-SDK/releases/download/$OpenClSdkVersion/OpenCL-SDK-$OpenClSdkVersion-Win-x64.zip" `
  'lib\OpenCL.lib' "OpenCL-SDK-$OpenClSdkVersion-Win-x64"

Remove-Item -Recurse -Force $downloads

function P([string] $Path) { $Path.Replace('\', '/') }

$cache = @"
# Generated by .github/scripts/fetch-windows-deps.ps1 -- use with: cmake -C <this file>
set(CMAKE_DISABLE_FIND_PACKAGE_PkgConfig ON CACHE BOOL "")

set(LibUSB_INCLUDE_DIRS "$(P "$libusb/include")" CACHE PATH "")
set(LibUSB_LIBRARIES    "$(P "$libusb/VS2022/MS64/dll/libusb-1.0.lib")" CACHE FILEPATH "")
set(LibUSB_DLL          "$(P "$libusb/VS2022/MS64/dll/libusb-1.0.dll")" CACHE FILEPATH "")

set(TurboJPEG_INCLUDE_DIRS "$(P "$turbojpeg/include")" CACHE PATH "")
set(TurboJPEG_LIBRARIES    "$(P "$turbojpeg/lib/turbojpeg.lib")" CACHE FILEPATH "")
set(TurboJPEG_DLL          "$(P "$turbojpeg/bin/turbojpeg.dll")" CACHE FILEPATH "")

set(GLFW3_INCLUDE_DIRS "$(P "$glfw/include")" CACHE PATH "")
set(GLFW3_LIBRARIES    "$(P "$glfw/lib-vc2022/glfw3dll.lib")" CACHE FILEPATH "")
set(GLFW3_DLL          "$(P "$glfw/lib-vc2022/glfw3.dll")" CACHE FILEPATH "")

set(OpenCL_INCLUDE_DIR "$(P "$opencl/include")" CACHE PATH "")
set(OpenCL_LIBRARY     "$(P "$opencl/lib/OpenCL.lib")" CACHE FILEPATH "")
"@
$cacheFile = Join-Path $DestDir 'deps.cmake'
Set-Content -Path $cacheFile -Value $cache -Encoding utf8NoBOM
Write-Host "Wrote $cacheFile"
